Q: CRC 16 bit (Polynomial 0x1021) CCITT calculation with initial value 0x0000 A: <p>What about this one?</p>
<pre><code>public static short GetCRC16(byte[] bytes)
{
    int crc = 0xFFFF;         
    int polynomial = 0x1021;  

    foreach (byte b in bytes)
    {

        crc ^= (b &lt;&lt; 8);

        for (int i = 0; i &lt; 8; i++)
        {
            if ((crc &amp; 0x8000) != 0)
                crc = (crc &lt;&lt; 1) ^ polynomial;
            else
                crc &lt;&lt;= 1;
        }
    }
    return (short)crc;
}
</code></pre>
